13	pub fn out_write(t: &str) {
14	    // CPython's text streams on Windows write CRLF; match them (every LF, as its TextIOWrapper does).
15	    #[cfg(windows)]
16	    let t = t.replace('\n', "\r\n");
17	    #[cfg(windows)]
18	    let t = t.as_str();
19	    OUT.with(|o| {
20	        let mut o = o.borrow_mut();
21	        if o.buf.len() + t.len() > 8192 {
22	            let b = std::mem::take(&mut o.buf);
23	            std::io::stdout().write_all(&b).ok();
24	            if t.len() >= 8192 {
25	                std::io::stdout().write_all(t.as_bytes()).ok();
26	                std::io::stdout().flush().ok();
27	                return;
28	            }
29	        }
30	        o.buf.extend_from_slice(t.as_bytes());
31	        if o.tty && t.contains('\n') {
32	            let b = std::mem::take(&mut o.buf);
33	            std::io::stdout().write_all(&b).ok();
34	            std::io::stdout().flush().ok();
35	        }
36	    });
37	}
