53	fn with_stdin<T>(f: impl FnOnce(&mut std::io::BufReader<std::io::Stdin>) -> T) -> T {
54	    STDIN.with(|s| {
55	        let mut s = s.borrow_mut();
56	        if s.is_none() {
57	            *s = Some(std::io::BufReader::new(std::io::stdin()));
58	        }
59	        f(s.as_mut().unwrap())
60	    })
61	}
62	pub fn read_line() -> Option<String> {
63	    with_stdin(|r| {
64	        let mut buf = Vec::new();
65	        match r.read_until(b'\n', &mut buf) {
66	            Ok(0) => None,
67	            Ok(_) => Some(String::from_utf8_lossy(&buf).into_owned()),
68	            Err(_) => None,
69	        }
70	    })
71	}
