51	// Clone by hand: the common cases are tested one by one before the full match, whose jump table the CPU
52	// mispredicts when floats, objects and tuples alternate (as in an autograd graph's inner loops).
53	impl Clone for V {
54	    #[inline]
55	    fn clone(&self) -> V {
56	        if let V::Float(f) = self {
57	            return V::Float(*f);
58	        }
59	        if let V::Obj(o) = self {
60	            return V::Obj(o.clone());
61	        }
62	        if let V::Int(i) = self {
63	            return V::Int(*i);
64	        }
65	        if let V::Tuple(t) = self {
66	            return V::Tuple(t.clone());
67	        }
68	        self.clone_slow()
69	    }
70	}
