1918	impl It {
1919	    // lists and tuples first, inline in the loop that runs them; the rest through one match
1920	    #[inline(always)]
1921	    pub fn next(&mut self) -> Result<Option<V>, E> {
1922	        if let It::Tuple(t, i) = self {
1923	            return Ok(t.get(*i).map(|x| {
1924	                *i += 1;
1925	                x.clone()
1926	            }));
1927	        }
1928	        if let It::List(l, i) = self {
1929	            let got = l.borrow().get(*i).cloned();
1930	            if got.is_some() {
1931	                *i += 1;
1932	                return Ok(got);
1933	            }
1934	            // An exhausted list iterator stays exhausted, as in CPython, even if the list grows afterwards.
1935	            *self = It::Done;
1936	            return Ok(None);
1937	        }
1938	        self.next_slow()
1939	    }
1940	    #[inline(never)]
1941	    fn next_slow(&mut self) -> Result<Option<V>, E> {
1942	        match self {
1943	            It::List(l, i) => {
1944	                let got = l.borrow().get(*i).cloned();
1945	                if got.is_some() {
1946	                    *i += 1;
1947	                    Ok(got)
1948	                } else {
1949	                    *self = It::Done;
1950	                    Ok(None)
1951	                }
1952	            }
1953	            It::Tuple(t, i) => {
1954	                if *i < t.len() {
1955	                    *i += 1;
1956	                    Ok(Some(t[*i - 1].clone()))
1957	                } else {
1958	                    Ok(None)
1959	                }
1960	            }
1961	            It::Vec(v) => Ok(v.next()),
1962	            It::Str(s, i) => {
1963	                if *i >= s.s.len() {
1964	                    return Ok(None);
1965	                }
1966	                if s.ascii {
1967	                    *i += 1;
1968	                    return Ok(Some(ch1(s.s.as_bytes()[*i - 1] as char)));
1969	                }
1970	                let c = s.s[*i..].chars().next().unwrap();
1971	                *i += c.len_utf8();
1972	                Ok(Some(ch1(c)))
1973	            }
1974	            It::Range(a, b, st) => {
1975	                if (*st > 0 && *a < *b) || (*st < 0 && *a > *b) {
1976	                    let v = *a;
1977	                    *a += *st;
1978	                    Ok(Some(V::Int(v)))
