280	// Drop every reference a garbage container holds. Only mutable containers are cleared; a Python-constructible
281	// cycle always passes through one of them, so breaking the mutable links breaks every cycle. Immutable
282	// containers in the garbage are released with the walk's own last clones.
283	fn gc_clear(v: &V) {
284	    // Move the contents out first and drop them after the borrow is released: dropping a value can run code
285	    // (an Ext's Drop, a generator's finally), which must not happen while the container is still borrowed.
286	    // A container currently borrowed by running user code is left alone (it cannot be garbage anyway, and
287	    // clearing it now would panic).
288	    match v {
289	        V::Obj(o) => {
290	            let Ok(mut d) = o.d.try_borrow_mut() else { return };
291	            let old = std::mem::replace(&mut *d, AStore::new());
292	            drop(d);
293	            let mut hold: Vec<V> = old.attrs.into_vec().into_iter().map(|(_, x)| x).collect();
294	            if let Some(dd) = old.dict {
295	                hold.push(V::Dict(dd));
296	            }
297	            if let Some(x) = o.take_inner() {
298	                hold.push(*x);
299	            }
300	            drop(hold);
301	        }
302	        V::List(l) => {
303	            let Ok(mut l) = l.try_borrow_mut() else { return };
304	            let old = std::mem::take(&mut *l);
305	            drop(l);
306	            drop(old);
307	        }
308	        V::Dict(d) => {
309	            let Ok(mut d) = d.try_borrow_mut() else { return };
310	            let old = std::mem::replace(&mut *d, Dict::new());
311	            drop(d);
312	            drop(old);
313	        }
314	        V::Set(s) => {
315	            let Ok(mut s) = s.try_borrow_mut() else { return };
316	            let old = std::mem::replace(&mut *s, PSet::new());
317	            drop(s);
318	            drop(old);
319	        }
320	        V::Deque(d) => {
321	            let Ok(mut d) = d.try_borrow_mut() else { return };
322	            let old = std::mem::take(&mut d.v);
323	            drop(d);
324	            drop(old);
325	        }
326	        V::Iter(it) => {
327	            let Ok(mut it) = it.try_borrow_mut() else { return };
328	            let old = std::mem::replace(&mut *it, It::Done);
329	            drop(it);
